using System;using System.Collections.Generic;using System.Drawing;using System.Drawing.Drawing2D;using System.Windows.Forms;
namespace CuteMouseEffects{
class ColorWheelControl:Control{Bitmap wheel;Color selected=Color.FromArgb(235,102,94);public event EventHandler ColorChanged;public Color SelectedColor{get{return selected;}set{selected=value;Invalidate();}}public ColorWheelControl(){SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer|ControlStyles.ResizeRedraw,true);Cursor=Cursors.Cross;}protected override void OnResize(EventArgs e){if(wheel!=null){wheel.Dispose();wheel=null;}base.OnResize(e);}protected override void OnMouseDown(MouseEventArgs e){Pick(e.Location);base.OnMouseDown(e);}protected override void OnMouseMove(MouseEventArgs e){if(e.Button==MouseButtons.Left)Pick(e.Location);base.OnMouseMove(e);}void Pick(Point p){float cx=Width/2f,cy=Height/2f,r=Math.Min(Width,Height)/2f-5,dx=p.X-cx,dy=p.Y-cy,d=(float)Math.Sqrt(dx*dx+dy*dy);if(d>r)return;selected=Hsv((float)((Math.Atan2(dy,dx)*180/Math.PI+360)%360),Math.Min(1,d/r),1);Invalidate();if(ColorChanged!=null)ColorChanged(this,EventArgs.Empty);}protected override void OnPaint(PaintEventArgs e){if(wheel==null)Build();e.Graphics.SmoothingMode=SmoothingMode.AntiAlias;if(wheel!=null)e.Graphics.DrawImageUnscaled(wheel,0,0);float[] h=ToHsv(selected);float r=Math.Min(Width,Height)/2f-5,a=(float)(h[0]*Math.PI/180),x=Width/2f+(float)Math.Cos(a)*r*h[1],y=Height/2f+(float)Math.Sin(a)*r*h[1];using(var b=new SolidBrush(selected))e.Graphics.FillEllipse(b,x-7,y-7,14,14);using(var q=new Pen(Color.White,3))e.Graphics.DrawEllipse(q,x-8,y-8,16,16);using(var q=new Pen(Color.FromArgb(65,45,42),1))e.Graphics.DrawEllipse(q,x-9,y-9,18,18);}void Build(){if(Width<2||Height<2)return;wheel=new Bitmap(Width,Height);float cx=Width/2f,cy=Height/2f,r=Math.Min(Width,Height)/2f-5;for(int y=0;y<Height;y++)for(int x=0;x<Width;x++){float dx=x-cx,dy=y-cy,d=(float)Math.Sqrt(dx*dx+dy*dy);if(d<=r)wheel.SetPixel(x,y,Hsv((float)((Math.Atan2(dy,dx)*180/Math.PI+360)%360),d/r,1));}}public static Color Hsv(float h,float s,float v){float c=v*s,x=c*(1-Math.Abs((h/60)%2-1)),m=v-c,r=0,g=0,b=0;if(h<60){r=c;g=x;}else if(h<120){r=x;g=c;}else if(h<180){g=c;b=x;}else if(h<240){g=x;b=c;}else if(h<300){r=x;b=c;}else{r=c;b=x;}return Color.FromArgb(255,(int)((r+m)*255),(int)((g+m)*255),(int)((b+m)*255));}static float[] ToHsv(Color c){float r=c.R/255f,g=c.G/255f,b=c.B/255f,max=Math.Max(r,Math.Max(g,b)),min=Math.Min(r,Math.Min(g,b)),d=max-min,h=0;if(d>0){if(max==r)h=60*((g-b)/d%6);else if(max==g)h=60*((b-r)/d+2);else h=60*((r-g)/d+4);}if(h<0)h+=360;return new[]{h,max==0?0:d/max,max};}protected override void Dispose(bool d){if(d&&wheel!=null)wheel.Dispose();base.Dispose(d);}}
class PreviewPoint{public float X,Y;}class PreviewParticle{public float X,Y,VX,VY;public int Age,Life,Slot;}class PreviewPulse{public float X,Y;public int Age,Kind;}
class EffectPreviewControl:Control{readonly Timer timer=new Timer();readonly List<PreviewPoint> trail=new List<PreviewPoint>();readonly List<PreviewParticle> particles=new List<PreviewParticle>();readonly List<PreviewPulse> pulses=new List<PreviewPulse>();readonly Random random=new Random(27);int frame,lastCycle=-1;float cx=55,cy=120,dragX,dragY;bool dragging;Color[] colors;public Color[] Colors{get{return colors;}set{colors=value;Invalidate();}}public EffectPreviewControl(){timer.Interval=30;timer.Tick+=delegate{Step();};timer.Start();SetStyle(ControlStyles.UserPaint|ControlStyles.AllPaintingInWmPaint|ControlStyles.OptimizedDoubleBuffer,true);}void Step(){frame++;int cycle=frame%300;if(cycle<lastCycle)trail.Clear();lastCycle=cycle;float u=cycle/299f;cx=38+u*(Width-76);cy=112+(float)Math.Sin(u*Math.PI*2)*34+(float)Math.Sin(u*Math.PI*5)*8;trail.Add(new PreviewPoint{X=cx,Y=cy});if(trail.Count>34)trail.RemoveAt(0);if(cycle==30||cycle==112){pulses.Add(new PreviewPulse{X=cx,Y=cy,Kind=cycle==30?0:1});Burst(cx,cy,cycle==30?1:2);}if(cycle==160)pulses.Add(new PreviewPulse{X=cx,Y=cy,Kind=2});if(cycle==202){dragging=true;dragX=cx;dragY=cy;}if(cycle==252){dragging=false;pulses.Add(new PreviewPulse{X=cx,Y=cy,Kind=3});Burst(cx,cy,2);}for(int i=pulses.Count-1;i>=0;i--){if(++pulses[i].Age>36)pulses.RemoveAt(i);}for(int i=particles.Count-1;i>=0;i--){var p=particles[i];p.Age++;p.X+=p.VX;p.Y+=p.VY;p.VY+=.018f;if(p.Age>p.Life)particles.RemoveAt(i);}Invalidate();}void Burst(float x,float y,int slot){for(int i=0;i<9;i++){double a=Math.PI*2*i/9+random.NextDouble()*.18;float v=1.1f+(float)random.NextDouble()*1.7f;particles.Add(new PreviewParticle{X=x,Y=y,VX=(float)Math.Cos(a)*v,VY=(float)Math.Sin(a)*v,Life=22+random.Next(10),Slot=(slot+i)%3});}}
 protected override void OnPaint(PaintEventArgs e){var g=e.Graphics;g.SmoothingMode=SmoothingMode.AntiAlias;using(var p=MagicPalette.Round(new Rectangle(0,0,Width-1,Height-1),22))using(var b=new SolidBrush(Color.FromArgb(31,34,34)))g.FillPath(b,p);using(var b=new SolidBrush(Color.FromArgb(38,255,255,255)))g.FillRectangle(b,18,18,Width-36,54);using(var b=new SolidBrush(Color.FromArgb(18,255,255,255)))g.FillRectangle(b,18,82,Width-36,Height-126);if(colors==null||colors.Length<5)return;DrawTrail(g);DrawPulses(g);DrawParticles(g);if(dragging){using(var q=Round(Color.FromArgb(205,colors[0]),6.2f))g.DrawLine(q,dragX,dragY,cx,cy);using(var q=Round(Color.FromArgb(235,colors[3]),2.0f))g.DrawLine(q,dragX,dragY,cx,cy);using(var b=new SolidBrush(colors[2]))g.FillEllipse(b,dragX-4,dragY-4,8,8);}CursorShapes.Draw(g,"star",new RectangleF(cx-5,cy-5,31,31),colors[0],colors[1],colors[2],colors[3],colors[4]);string state=dragging?"拖动牵引":frame%300<70?"移动与左击":frame%300<145?"移动与右击":frame%300<190?"滚轮动作":"移动拖尾";using(var f=new Font("Microsoft YaHei UI",8.5f))using(var b=new SolidBrush(Color.FromArgb(195,220,220,215)))g.DrawString("实际节奏预览  ·  "+state,f,b,20,Height-33);}
 void DrawTrail(Graphics g){for(int i=1;i<trail.Count;i++){float f=i/(float)trail.Count;var a=trail[i-1];var b=trail[i];using(var q=Round(Color.FromArgb((int)(115*f),colors[0]),7.4f*(.55f+.45f*f)))g.DrawLine(q,a.X,a.Y,b.X,b.Y);using(var q=Round(Color.FromArgb((int)(225*f),colors[1]),2.6f))g.DrawLine(q,a.X,a.Y,b.X,b.Y);using(var q=Round(Color.FromArgb((int)(225*f),colors[3]),.8f))g.DrawLine(q,a.X,a.Y,b.X,b.Y);}}
 void DrawPulses(Graphics g){foreach(var p in pulses){float t=p.Age/36f,f=1-t,r=8+t*(p.Kind==3?58:44);if(p.Kind==2){for(int i=0;i<3;i++){float y=p.Y-8-i*11-t*15;using(var q=Round(Color.FromArgb((int)(235*f),i%2==0?colors[2]:colors[3]),2.6f)){g.DrawLine(q,p.X-7,y+5,p.X,y);g.DrawLine(q,p.X,y,p.X+7,y+5);}}}else if(p.Kind==1){PointF[] h=new PointF[6];for(int i=0;i<6;i++){double a=i*Math.PI/3+t*.5;h[i]=new PointF(p.X+(float)Math.Cos(a)*r,p.Y+(float)Math.Sin(a)*r);}using(var q=new Pen(Color.FromArgb((int)(220*f),colors[2]),2.2f))g.DrawPolygon(q,h);}else{using(var q=new Pen(Color.FromArgb((int)(205*f),colors[p.Kind==3?2:3]),2.6f))g.DrawEllipse(q,p.X-r,p.Y-r,r*2,r*2);using(var q=new Pen(Color.FromArgb((int)(170*f),colors[1]),1.3f))g.DrawArc(q,p.X-r*.72f,p.Y-r*.72f,r*1.44f,r*1.44f,-35+p.Age*4,250);}}}
 void DrawParticles(Graphics g){foreach(var p in particles){float f=1-p.Age/(float)p.Life,s=2.2f+f*2;using(var b=new SolidBrush(Color.FromArgb((int)(235*f),colors[p.Slot+1])))g.FillEllipse(b,p.X-s/2,p.Y-s/2,s,s);}}static Pen Round(Color c,float w){var p=new Pen(c,w);p.StartCap=p.EndCap=LineCap.Round;p.LineJoin=LineJoin.Round;return p;}protected override void Dispose(bool d){if(d)timer.Dispose();base.Dispose(d);}}
class CustomThemeDialog:Form{readonly string[] labels={"轮廓","主色","辅色","光晕","高光"};readonly Color[] colors=new Color[5];readonly Panel[] chips=new Panel[5];readonly ColorWheelControl wheel;readonly EffectPreviewControl preview;readonly TextBox nameBox;int active;public string ThemeName{get{return string.IsNullOrWhiteSpace(nameBox.Text)?"我的配色":nameBox.Text.Trim();}}public Color[] ThemeColors{get{return(Color[])colors.Clone();}}public CustomThemeDialog(EffectTheme theme){Text="创建自定义配色";ClientSize=new Size(890,535);StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MaximizeBox=false;MinimizeBox=false;BackColor=MagicPalette.Back;Font=new Font("Microsoft YaHei UI",9);colors[0]=theme.Shadow;colors[1]=theme.Primary;colors[2]=theme.Secondary;colors[3]=theme.Glow;colors[4]=theme.Core;Controls.Add(new Label{Text="按顺序选择五种颜色",Font=new Font("Microsoft YaHei UI",18,FontStyle.Bold),ForeColor=MagicPalette.Ink,BackColor=MagicPalette.Back,Location=new Point(28,20),AutoSize=true});Controls.Add(new Label{Text="每次点击色轮都会更新当前色位，右侧按程序真实节奏预览鼠标动作。",ForeColor=MagicPalette.Soft,BackColor=MagicPalette.Back,Location=new Point(31,60),AutoSize=true});nameBox=new TextBox{Text=theme.Name=="自定义"?"我的配色":theme.Name,Location=new Point(30,92),Size=new Size(286,30),MaxLength=16};Controls.Add(nameBox);wheel=new ColorWheelControl{Location=new Point(42,145),Size=new Size(248,248),SelectedColor=colors[0]};wheel.ColorChanged+=delegate{colors[active]=wheel.SelectedColor;RefreshColors();};Controls.Add(wheel);for(int i=0;i<5;i++){int k=i;var p=new Panel{Location=new Point(25+i*64,414),Size=new Size(58,58),Cursor=Cursors.Hand};p.Click+=delegate{SetActive(k);};chips[i]=p;Controls.Add(p);}preview=new EffectPreviewControl{Location=new Point(346,92),Size=new Size(514,316),Colors=(Color[])colors.Clone()};Controls.Add(preview);Controls.Add(new Label{Text="效果预览",Font=new Font("Microsoft YaHei UI",10,FontStyle.Bold),ForeColor=MagicPalette.Ink,BackColor=MagicPalette.Back,Location=new Point(349,61),AutoSize=true});var next=new Button{Text="下一色位",Location=new Point(676,446),Size=new Size(88,38)};next.Click+=delegate{SetActive((active+1)%5);};Controls.Add(next);var save=new Button{Text="保存配色",DialogResult=DialogResult.OK,Location=new Point(776,446),Size=new Size(84,38),BackColor=MagicPalette.MintDark,ForeColor=Color.White,FlatStyle=FlatStyle.Flat};save.FlatAppearance.BorderSize=0;Controls.Add(save);AcceptButton=save;RefreshColors();SetActive(0);}void SetActive(int i){active=i;wheel.SelectedColor=colors[i];RefreshColors();}void RefreshColors(){for(int i=0;i<5;i++){chips[i].BackColor=colors[i];chips[i].Controls.Clear();chips[i].BorderStyle=i==active?BorderStyle.Fixed3D:BorderStyle.FixedSingle;var l=new Label{Text=(i+1)+"\n"+labels[i],ForeColor=Contrast(colors[i]),BackColor=colors[i],TextAlign=ContentAlignment.MiddleCenter,Dock=DockStyle.Fill,Font=new Font("Microsoft YaHei UI",7.5f,FontStyle.Bold)};int k=i;l.Click+=delegate{SetActive(k);};chips[i].Controls.Add(l);}preview.Colors=(Color[])colors.Clone();}static Color Contrast(Color c){return c.R*.299+c.G*.587+c.B*.114>150?Color.FromArgb(35,35,35):Color.White;}}
